import{z as E,x as I,o as t,c as p,q as r,j as i,D as e,d as n,s as l,S as o,b as d}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"软件流水","description":"","frontmatter":{"title":"软件流水","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/software-pipelining.md","filePath":"cs/software-pipelining.md","lastUpdated":1791413859000}'),A={name:"cs/software-pipelining.md"};function B(m,a,c,h,u,f){const s=I("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="软件流水" tabindex="-1">软件流水 <a class="header-anchor" href="#软件流水" aria-label="Permalink to &quot;软件流水&quot;">​</a></h1><div class="epigraph"><p>模调度让连续迭代重叠：核（kernel）每 II 拍启动一圈，序言与收尾补满流水。目标是吞吐，不是单圈最短。</p><footer>—— 据 Rau and Glaeser；Lam, Software Pipelining, 1988；Rau, Iterative Modulo Scheduling 整理</footer></div><p>上一课<a href="/cs/list-scheduling">表调度</a>优化单块。循环要<strong>跨迭代重叠</strong>。缺口是软件流水 / 模调度：启动间隔 II 受资源与环依赖约束。本课钉 II、kernel、prologue/epilogue，不写 VLIW 模板全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表调度一圈内排完再下一圈，ALU 仍闲。流水：迭代 \\(i\\) 的 load 与 \\(i+1\\) 的算重叠。II 下界：\\(\\max(\\mathrm{ResMII}, \\mathrm{RecMII})\\)。缺口是<strong>选 II 并放置</strong>，不是块内就绪表。</p><p><span class="marginnote">数字实例：若循环体一次 load 要 4 拍才返回，且环依赖要求相邻迭代至少隔 4 拍，RecMII 就是 4；哪怕机器每拍能发 2 条指令、把 ResMII 压到 3，II 也只能取 \\(\\max(3,4)=4\\)——瓶颈在依赖环，不在发射口宽度。</span></p><p>若寄存器寿命跨过 II 太长，要旋转或放弃。展开可减 RecMII。</p><h3 id="软件流水不是硬件流水线重讲" tabindex="-1">软件流水不是硬件流水线重讲 <a class="header-anchor" href="#软件流水不是硬件流水线重讲" aria-label="Permalink to &quot;软件流水不是硬件流水线重讲&quot;">​</a></h3><p>组成课五级是 CPU；本课编译器改指令序与核循环。对象不同。</p><p><span class="marginnote">Lam 1988。Rau IMS。Itanium/VLIW 是历史主场；超标量上收益看循环。本课不把 GPU 的软件流水当必须。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算 MII。从 MII 起试调度核。失败则 II++。生成序言（填满）、核、收尾。处理模变量（同一物理寄存器的轮转）。</p>',12)),(t(),i(o,null,{default:e(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%BE%AA%E7%8E%AF%E4%BD%93%22%5D%20--%3E%20MII%5B%22Res%2FRec%20MII%22%5D%0A%20%20MII%20--%3E%20KER%5B%22%E6%A8%A1%E8%B0%83%E5%BA%A6%E6%A0%B8%22%5D%0A%20%20KER%20--%3E%20PE%5B%22%E5%BA%8F%E8%A8%80%20%2F%20%E6%94%B6%E5%B0%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=d("p",null,"与向量化：可先向量化再流水，或放弃其一。别名环依赖会抬 RecMII。",-1)),(t(),i(o,null,{default:e(()=>[l(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E7%AE%97%E4%B8%8B%E7%95%8C%20II%20%3D%20max%20ResMII%20RecMII%22%5D%20--%3E%20T%5B%22%E4%BB%A5%E5%BD%93%E5%89%8D%20II%20%E8%AF%95%E6%A8%A1%E8%B0%83%E5%BA%A6%22%5D%0A%20%20T%20--%3E%20C%7B%22%E6%89%80%E6%9C%89%E6%8C%87%E4%BB%A4%E6%94%BE%E5%BE%97%E4%B8%8B%20%E5%AF%84%E5%AD%98%E5%99%A8%E5%AF%BF%E5%91%BD%E4%B9%9F%E4%B8%8D%E8%B6%85%E9%99%90%3F%22%7D%0A%20%20C%20--%20%22%E6%98%AF%22%20--%3E%20K%5B%22%E7%94%9F%E6%88%90%E5%BA%8F%E8%A8%80%20%2F%20%E6%A0%B8%20%2F%20%E6%94%B6%E5%B0%BE%22%5D%0A%20%20C%20--%20%22%E5%90%A6%22%20--%3E%20I%5B%22II%20%E5%8A%A0%E4%B8%80%22%5D%0A%20%20I%20--%3E%20T%0A%20%20K%20--%3E%20R%5B%22%E6%A8%A1%E5%8F%98%E9%87%8F%E7%94%A8%E5%AF%84%E5%AD%98%E5%99%A8%E8%BD%AE%E8%BD%AC%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">直觉类比：序言与收尾像流水线的开线与收线——第一批进料时机器还没满负荷（序言），最后一批出料时逐渐空出（收尾），只有稳定中段才是核：每 II 拍放进一圈新迭代，同时吐出一圈结果。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代码体积：序言收尾胀。调试困难。异常：核中间出错，状态难映射源迭代——限制投机。不要对含调用的循环强流水除非内联完。</p><p><span class="marginnote">常见误区：以为软件流水总能加速。寄存器寿命跨多个迭代时轮转寄存器会膨胀，序言收尾让代码体积成倍增长，核中间抛异常也很难对应回某个源迭代——对含调用或不规则控制流的循环，强流水常常得不偿失。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 SMS 算法变体。后课默认：无环或弱环的内层可模调度。下一课关键路径：给表调度/流水当优先级的路径长度。</p><p>也不把软件流水当 OS 管道。</p><p><span class="marginnote">术语翻译：模调度（modulo scheduling）的「模」指核循环按 II 取模循环——第 \\(i\\) 圈迭代在第 \\(i \\bmod \\mathrm{II}\\) 拍进入核，同一拍里最多有 II 圈不同迭代的片段在并行；所谓 kernel 就是这样一段重复 II 拍就循环一次的紧凑代码。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>软件流水：迭代重叠，II 受资源与环约束。</li><li>核 + 序言/收尾；寄存器轮转是实现细节。</li><li>与表调度分层：块内 vs 跨圈。</li><li>出处：Lam, 1988；Rau 模调度；对照 Hennessy–Gross。</li></ul>',10))])}const g=E(A,[["render",B]]);export{D as __pageData,g as default};
